queries.cql:
// CrowdStrike CQL for Combo List Iteration Pattern
// Repository: flame-banking-auth-logs
// Aggregation that cannot be expressed in Sigma:
// Original condition: selection | count(distinct username) by source_ip > 15 and stddev(inter_event_time) by source_ip < 500ms
event_type="login_attempt"
auth_result="failure"
| groupBy(source_ip, function=[count(as=event_count), collect(username)])
| event_count > 15
